#!/usr/bin/env python3
"""
ios-icon-fix.py
Legt an: public/apple-touch-icon.png, public/icon-192.png,
         public/icon-512.png, public/manifest.json
Patcht:  app/layout.tsx (icons + manifest im metadata-Export)
Guard:   Abbruch wenn apple-touch-icon.png bereits existiert
"""
import sys, base64, re
from pathlib import Path

ROOT = Path(__file__).parent

# Guard
guard = ROOT / "public" / "apple-touch-icon.png"
if guard.exists():
    print("ABBRUCH: apple-touch-icon.png existiert bereits.")
    sys.exit(0)

# PNG-Icons
B64 = {
    "public/apple-touch-icon.png": "",
    "public/icon-192.png":         "",
    "public/icon-512.png":         "",
}
for rel, b64 in B64.items():
    p = ROOT / rel
    p.parent.mkdir(parents=True, exist_ok=True)
    p.write_bytes(base64.b64decode(b64))
    print(f"  Geschrieben: {rel} ({p.stat().st_size} B)")

# manifest.json
manifest_content = """{
  "name": "Kreta 2026",
  "short_name": "Kreta",
  "description": "Reiseplanung Luca & Jan · 01.-09. Juli 2026",
  "start_url": "/",
  "display": "standalone",
  "background_color": "#fbfdf9",
  "theme_color": "#0e302e",
  "icons": [
    { "src": "/apple-touch-icon.png", "sizes": "180x180", "type": "image/png" },
    { "src": "/icon-192.png", "sizes": "192x192", "type": "image/png", "purpose": "any maskable" },
    { "src": "/icon-512.png", "sizes": "512x512", "type": "image/png", "purpose": "any maskable" }
  ]
}"""
mf = ROOT / "public" / "manifest.json"
mf.write_text(manifest_content, encoding="utf-8")
print("  Geschrieben: public/manifest.json")

# layout.tsx patchen
layout = ROOT / "app" / "layout.tsx"
if not layout.exists():
    print(f"FEHLER: {layout} nicht gefunden.")
    sys.exit(1)

src = layout.read_text(encoding="utf-8")

if "apple-touch-icon" in src:
    print("  layout.tsx: apple-touch-icon bereits vorhanden, uebersprungen.")
else:
    icons_block = (
        "  icons: {\n"
        "    apple: \"/apple-touch-icon.png\",\n"
        "    icon: [\n"
        "      { url: \"/icon-192.png\", sizes: \"192x192\", type: \"image/png\" },\n"
        "      { url: \"/icon-512.png\", sizes: \"512x512\", type: \"image/png\" },\n"
        "    ],\n"
        "  },\n"
    )
    manifest_prop = '  manifest: "/manifest.json",\n'

    m = re.search(r"(  description: [^\n]+\n)", src)
    if m:
        old = m.group(1)
        assert src.count(old) == 1, f"Mismatch: kommt {src.count(old)}x vor"
        new = old + icons_block + manifest_prop
        src = src.replace(old, new)
        print("  layout.tsx: icons + manifest hinzugefuegt")
    else:
        # Fallback: vor dem schliessenden }; des metadata-Exports
        m2 = re.search(r"(export const metadata[\s\S]*?)(};)", src)
        if m2:
            old = m2.group(2)
            insert = icons_block + manifest_prop + old
            # Nur letztes }; des metadata-Blocks ersetzen
            pos = src.rfind("};")
            if pos != -1:
                src = src[:pos] + icons_block + manifest_prop + src[pos:]
                print("  layout.tsx: icons + manifest via Fallback hinzugefuegt")
            else:
                print("  WARNUNG: Kein Anker gefunden. Bitte manuell ergaenzen:")
                print(icons_block + manifest_prop)
        else:
            print("  WARNUNG: metadata-Export nicht gefunden. Bitte manuell ergaenzen:")
            print(icons_block + manifest_prop)

    layout.write_text(src, encoding="utf-8")
    print("  layout.tsx: gespeichert")

print()
print("FERTIG")
print()
print("Commit-Vorschlag:")
print("  fix: add apple-touch-icon, PWA manifest and iOS home screen icons")
